// Lecture integrale article - screening approfondi sur PDF complet
// FULLTEXT_SCREENING_v1 (v0.2.6)
const PROXY = 'http://host.docker.internal:3456';
const items = $input.all();
const articles = items.map(i => i.json);
const question = (articles[0] && articles[0].question) || '';
const criteria = (articles[0] && articles[0].criteria) || '';
// FULLTEXT_AI_SETTINGS_v1 - reutilise les reglages avances du screening (strictesse + regles)
let __ftAi = (articles[0] && articles[0]._ai_settings) || {};
if (typeof __ftAi.strictness !== 'number') { try { const __fc = await this.helpers.httpRequest({ method:'GET', url:'http://host.docker.internal:8080/api/config', timeout:5000, json:true }) || {}; __ftAi = { strictness: __fc.fulltext_strictness, custom_rules: __fc.fulltext_custom_rules }; } catch(e) {} }
const __ftStrict = (typeof __ftAi.strictness === 'number') ? __ftAi.strictness : 50;
const __ftRules = (__ftAi.custom_rules || '').toString().trim();
let __ftGuidance = '';
if (__ftStrict <= 25) __ftGuidance = '\n\nTONE: Be CONSERVATIVE - when in doubt, prefer Include or Maybe over Exclude.';
else if (__ftStrict >= 75) __ftGuidance = '\n\nTONE: Be STRICT - only Include if ALL criteria are clearly met in the full text; when in doubt, Exclude.';
else if (__ftStrict >= 60) __ftGuidance = '\n\nTONE: Slightly strict - when in doubt, lean toward Exclude.';
else if (__ftStrict <= 40) __ftGuidance = '\n\nTONE: Slightly conservative - when in doubt, lean toward Maybe.';
const __ftRulesBlock = __ftRules ? ('\n\n=== USER-DEFINED RULES (must be respected) ===\n' + __ftRules) : '';

// LECTURE_MESUREE_v1 (mesure du 2026-09-10) : UN SEUL ANALYSEUR pour les deux decisions de la
// double lecture. La seconde decision passait par un repli laxiste (le premier des trois mots
// trouve dans la reponse) et echappait a la regle « Include sans justification devient Maybe » :
// sur les memes reponses de modele, le noeud double mesurait 5 paires et kappa 0,333, le second
// avis du moteur (qui rejoue CE noeud avec le modele 2 en premier modele) 4 paires et kappa
// 0,636. Une phrase libre concluant a l'exclusion (« ... does not include the target population;
// it should be excluded. ») y valait Include et formait une paire en accord. Rend
// { decision, reason }, ou null quand la reponse ne porte aucune ligne « Decision » lisible.
function __ftLire(raw) {
  const s = String(raw || '');
  const m = s.match(/decision[\s:=]+(include|maybe|exclude)/i);
  if (!m) return null;
  // BORNE DECLAREE (lot du 2026-09-21, mesure du 2026-09-28) : ce lecteur n'a pas de branche
  // de repli, et une etiquette « Decision » mise en forme ou absente ne se lit pas. Ce noeud
  // execute au commit e912d7b comme apres sur les 5 formes de la liste BORNES_DECISION_LI
  // de tests/test_etiquette_mise_en_forme.py : les 5 rendent le statut « llm_error »,
  // celui d'une lecture en echec (LECTURE_ILLISIBLE_v1, plus bas), et gardent la decision
  // initiale, mesuree valant Include puis Maybe ; aucune n'entre comme une lecture. Une
  // reponse JUSTIFIEE sous une etiquette en gras y est perdue aussi ; la rendre lisible
  // changerait des decisions : decision laissee a l'auteur.
  const w = m[1].toLowerCase();
  let d = w.indexOf('inc') === 0 ? 'Include' : (w.indexOf('exc') === 0 ? 'Exclude' : 'Maybe');
  let r = '';
  // RAISON_VIDE_v1 RENDU ICI, ET ETIQUETTE_MISE_EN_FORME_v1 (2026-09-21). Deux defauts mesures
  // le 2026-09-21 en executant ce noeud sur cas fabriques. (1) Le blanc qui suit « Reason: »
  // avalait le saut de ligne : « Decision: Include / Reason: (vide) / Category: none » rendait
  // la justification « Category: none » et gardait Include, la garde « Include sans
  // justification devient Maybe » etant contournee. (2) La coupe de l'etiquette, faite sur un
  // saut de ligne suivi du nom NU, ne voyait pas « **Category:** ». MESURE RECOMPTEE
  // LE 2026-09-23 SUR L'ETAT LIVRE, ce noeud au commit e912d7b contre ce noeud, 18 formes
  // fabriquees portees par « Decision: Include » (listes FORMES_LI, VACUITE_LI et BORNES_LI du
  // fichier de cas, plus une ligne d'etiquette de niveau de certitude) : 14 rendaient Include et
  // rendent desormais Maybe (etiquette nue ou mise en forme, justification faite de seule mise
  // en forme, retour chariot seul) ; les 4 autres ne changent pas, les 3 de BORNES_LI (borne
  // dite plus bas) et la limite dite ci-dessous. Le saut
  // de ligne avale est donc rendu comme au tri, la mise en forme est admise avant le nom de
  // l'etiquette, et une justification qui ne porte que de la mise en forme est vide. LIMITE : le
  // prompt de ce noeud, relu le 2026-09-29, tient en TROIS lignes (Decision, Reason, Category) :
  // la coupe connait « Category » et, depuis le 2026-09-29, « Decision » (COUPE_DECISION_LI_v1,
  // plus bas), et une ligne d'etiquette de niveau de
  // certitude, que ce prompt ne demande pas, reste dans la justification. Ce noeud ne NOMME pas
  // cette etiquette, et une garde du depot le lui interdit
  // (tests/test_etalonnage_sources_et_effectifs.py, cas
  // test_LI_aucun_PRODUCTEUR_ne_rend_de_confiance_propre_a_la_lecture_integrale) : l'ecran
  // affirme que la lecture integrale ne rend pas de certitude propre. Cas de ce correctif :
  // tests/test_etiquette_mise_en_forme.py.
  // LA COUPE EXIGE LES DEUX-POINTS, COMME CELLE DU TRI (2026-09-21). Ecrite sans eux, elle
  // coupait a toute ligne OUVRANT par le mot de l'etiquette, et la tolerance de mise en
  // forme posee plus haut le meme jour a elargi ce qu'elle mordait. MESURE RECOMPTEE LE
  // 2026-09-23 SUR L'ETAT LIVRE, ce noeud contre une copie dont la coupe n'exige plus les
  // deux-points, 27 reponses fabriquees (les 18 formes dites plus haut, les 8 de la liste
  // FORMES_CATEGORIE_LI et la reponse AMPUTEE du fichier de cas) : 2 changent. L'une est une
  // justification de deux puces dont la seconde ouvre par ce mot, sans deux-points : sans eux
  // elle tombe de 89 a 33 caracteres, sa seconde puce detruite. C'est la famille de defaut que la regle de 2026-09-04 avait fermee au
  // tri, ou une coupe trop large detruisait 263 des 339 caracteres d'une justification
  // legitime, mesuree alors sur des reponses reelles. Avec les deux-points cette
  // justification arrive entiere (89 caracteres recomptes). L'autre est la BORNE : une
  // etiquette separee de sa valeur par un tiret au lieu des deux-points n'est plus coupee et
  // reste donc la justification, verdict Include garde. La coupe n'admet devant le nom que
  // le blanc, le chevron, l'etoile, le souligne, le diese et le tiret. Parmi les formes
  // jouees, la contournent, verdict Include garde au commit e912d7b comme sur l'etat livre,
  // les 3 formes de la liste BORNES_LI (liste NUMEROTEE, puce typographique, tiret au lieu
  // des deux-points) et les 3 de la liste BORNES_CARACTERES_LI (puce « + », etiquette entre
  // accents graves, et une justification faite de « + » seuls, que la regle de vacuite ne
  // connait pas ; mesure du 2026-09-29, ce noeud execute), et les 3 formes de lecture
  // integrale de la liste BORNES_MOT_DEVANT, une etiquette precedee de mots : « Final
  // decision: » (mesure du 2026-09-30, ce noeud execute au commit e912d7b et sur l'etat
  // livre), puis la syntaxe que le prompt de ce noeud ecrit lui-meme, « Line 3 - Category: »,
  // seule ou dans la copie des trois lignes du prompt ; et les 8 formes de lecture integrale
  // des listes BORNES_MOT_APRES, BORNES_MEME_LIGNE et BORNES_SANS_MOT : un mot entre le nom et
  // les deux-points (« Category name: »), une etiquette nue ou mise en forme ecrite sur la
  // ligne meme de « Reason: », une justification faite de « N/A », d'un tiret long, d'une
  // puce ronde, de points de suspension ou d'une cloture de bloc de code. Ces 10 formes,
  // mesure du 2026-10-06, ce noeud execute au commit e912d7b et sur l'etat livre au tour 6 :
  // Include garde, l'etiquette ou le signe pour justification, aux deux etats ; les couper
  // est une decision laissee a l'auteur. Cette enumeration se borne aux formes jouees. Cas :
  // tests/test_etiquette_mise_en_forme.py.
  // BORNE DECLAREE (lot du 2026-09-21, mesure du 2026-09-28), la meme qu'au tri : l'etiquette
  // « Reason » ELLE-MEME mise en forme n'est pas lue. Ce noeud execute sur les 6 formes du
  // tri, au commit e912d7b comme apres : 4 perdent la justification (un Include y devient
  // Maybe), 2 gardent la marque en tete. Cas BORNE de tests/test_etiquette_mise_en_forme.py.
  // COUPE_DECISION_LI_v1 (lot du 2026-09-21, mesure du 2026-09-29). La coupe ne connaissait
  // que « Category », alors que le prompt de ce noeud demande aussi « Decision » : une ligne
  // « Decision: » apres un « Reason: » vide devenait la justification, et la garde « Include
  // sans justification devient Maybe », plus bas, ne la voyait pas. Mesure du 2026-09-29, ce
  // noeud execute au commit e912d7b, sur l'etat livre au tour 4 et avec cette coupe, sur les
  // reponses fabriquees des listes DECISION_LI et TEMOINS_DECISION_LI de
  // tests/test_etiquette_mise_en_forme.py : les 5 reponses de DECISION_LI rendaient Include,
  // une ligne « Decision: » pour justification, et rendent Maybe ; des 4 temoins, les 2
  // justifications suivies d'une ligne « Decision: » la gardaient collee derriere elles et
  // arrivent seules, les 2 autres (le mot sans deux-points en tete d'une puce, puis au
  // milieu d'une ligne) ne changent pas. CE GESTE CHANGE DONC DES DECISIONS FABRIQUEES, Include
  // vers Maybe, et le compte de 5 se borne a la liste DECISION_LI : la famille est plus large.
  // Ce noeud execute au commit e912d7b, sur l'etat livre au tour 4 et avec cette coupe
  // (mesure du 2026-09-30, et du 2026-10-05 pour la huitieme reponse) : les 8 reponses de la
  // liste DECISION_LI_FAMILLE (decision contraire, capitales, signe egal, gras entier,
  // citation, blanc avant les deux-points, tabulation, retours chariot seuls) rendaient aussi
  // Include, des lignes d'etiquette pour seule justification, et rendent Maybe. DEUX LIMITES,
  // les memes qu'au tri depuis le commit (les deux noeuds executes aux memes etats, mesures du
  // 2026-09-30 puis du 2026-10-05). Une justification ecrite sur une ligne « Decision: » qui
  // suit un « Reason: » vide n'est pas lue, et la reponse rend Maybe (elle rendait Include,
  // cette ligne pour justification, au commit et au tour 4). La phrase qui SUIT une ligne
  // « Decision: » placee apres la justification est perdue, decision gardee (elle restait
  // collee a la justification avec cette ligne au commit et au tour 4). Cas LIMITE du fichier
  // cite. COMPTE SUR TOUT CE FICHIER, joue le 2026-10-06 dans son etat final sur l'etat livre
  // au tour 4, ou ce noeud ne differe de l'etat livre que par cette coupe : 18 cas y
  // echouent, 15 sur une decision Include que ce geste rend Maybe, les autres sur une
  // justification seulement. Compte borne aux formes jouees. Cas fabriques seulement.
  const rm = s.match(/reason([\s:=]+)([\s\S]{0,2000})/i);
  if (rm) r = ((/[\r\n]/.test(rm[1]) ? '\n' : '') + rm[2]).split(/\n\n|\r\n\r\n/)[0].split(/[\r\n][\s>*_#-]*(?:category|decision)[*_]*\s*[:=]/i)[0].trim().substring(0, 2000);
  if (/^[\s>*_#-]*$/.test(r)) r = '';
  // Securite : si pas de reason et qu'on a une decision, marquer
  if (!r) r = '(no reason returned)';
  // Securite scientifique : Include sans reason -> Maybe (cf v0.2.5 #37)
  if (d === 'Include' && /^\(no reason/i.test(r)) {
    d = 'Maybe';
    r = 'LLM a propose Include mais sans justification verifiable - reclasse Maybe pour verification manuelle';
  }
  return { decision: d, reason: r };
}

console.log('[Fulltext Screening] ' + articles.length + ' articles candidats');
// AVANCEMENT_SANS_MODELE_v1 (2026-09-28, lot suivi). La barre du run ne comptait que les appels
// au modele, faits a la porte du relais : les articles que ce noeud passe SANS appeler le
// modele (exclus sur resume, sans PDF, PDF illisible) ne l'avancaient pas. Mesure de l'auteur
// du 2026-09-21 : 651 evaluees et 113 PDF illisibles sur 764, donc une barre finie a 651 sur
// 764. Chacun compte desormais pour un pas, publie par la route que les noeuds sans modele
// emploient deja (/api/module-progress/tick, corps { n, sans_travail }, jamais de position). Les pas
// s'accumulent et partent AVANT chaque lecture de PDF (jusqu'a 60 s en echec) et a la fin de
// chaque passe : une suite d'echecs fait bouger la barre, un bloc d'exclus ne coute qu'un
// appel. La seconde passe fait de meme pour les articles qu'elle ne relit pas ; la route de
// depart double le total quand elle est prevue (src/server.py, `_seconde_passe_prevue`).
// Cas : tests/test_lecture_integrale_avance_sans_modele.py.
let __ftSautes = 0;
// SANS_TRAVAIL_v1 (2026-09-28) : le corps dit aussi combien de ces pas n'ont rien lu ni appele
// (exclus sur resume, sans PDF, non relus en seconde passe). Le PDF illisible a coute une
// tentative de lecture, jusqu'a 60 s : il reste un pas ordinaire. Le temps restant de l'ecran
// retire les premiers du debit ; refutation du tour 2 : 700 exclus en tete puis cinq appels
// payes, et l'ecran annoncait « moins de 2 minutes » pour 59 lectures a faire.
let __ftSansTravail = 0;
// PAS_NOMMES_v1 (2026-10-08) : le corps des pas porte le mode du run (__ftMode, declare plus
// bas, avant le premier envoi). Sans lui, la route donnait ces pas au run ouvert le plus
// recemment : refutation du tour 8, 700 pas d'une lecture integrale passes sur un tri ouvert
// apres elle (50 sur 50, 650 au-dela de son total), la lecture restant a 0 sur 764.
let __ftSeconde = false;
async function __ftAvancer() {
  if (__ftSautes <= 0) return;
  const n = __ftSautes, k = __ftSansTravail;
  __ftSautes = 0; __ftSansTravail = 0;
  try { await this.helpers.httpRequest({ method: 'POST', url: 'http://host.docker.internal:8080/api/module-progress/tick', body: JSON.stringify({ n: n, sans_travail: k, mode: __ftMode }), headers: { 'Content-Type': 'application/json' }, timeout: 3000 }); } catch (__e) {}
}
// ETAPE_DECLAREE (2026-09-28) : ce noeud dit qu'il entre et qu'il sort, comme « Expand Results »
// du tri et « Assemble Results » du routeur ; la carte du module nomme alors la phase. La
// seconde lecture se declare a part, plus bas. La sortie est declaree par tous les chemins
// (bloc finally en fin de noeud).
const __ftMode = String((articles[0] && articles[0]._module_mode) || 'fulltext-screening');
async function __ftEtape(corps) {
  try { await this.helpers.httpRequest({ method: 'POST', url: 'http://host.docker.internal:8080/api/etape', body: JSON.stringify(Object.assign({ mode: __ftMode }, corps)), headers: { 'Content-Type': 'application/json' }, timeout: 8000 }); } catch (__e) {}
}
await __ftEtape.call(this, { noeud: 'Run Fulltext Screening', phase: 'entree', n: articles.length });
try {

// SECONDE_LECTURE_DE_CETTE_EXECUTION_v1 (refutation P2, mesure du 2026-09-10) : une seconde
// lecture ne vaut que face a la premiere lecture de la MEME execution. Le planificateur charge un
// dossier de run comme corpus (pipeline._articles_from_folder) et ne retire que les cles a tiret
// bas : la seconde lecture, l'etiquette d'accord et le modele 2 d'un run A double entraient dans
// une lecture B. Lue en simple, B ressortait avec les 4 secondes lectures de A ; doublee, avec le
// modele 2 en echec sur 2 rapports, elle en portait 4 pour 2 paires mesurees, et le moteur, qui
// recalcule l'accord depuis ces champs, publiait kappa 0,0 au lieu de 1,0. Ils sont retires ICI,
// de chaque article, quelle que soit sa branche : c'est la seule protection, la notice sautee et
// la reponse du modele 2 n'en ont plus de propre. Cout accepte : un rapport repris dont le modele
// 2 echoue a la reprise perd sa paire. screening_model2 reste (le tri sur resume, l'extraction
// et le second avis l'ecrivent aussi) : sans seconde decision, il ne forme aucune paire.
// LA TRACE D'ARBITRAGE D'UN AUTRE RUN AUSSI (refutation P3, mesure du 2026-09-10). L'arbitrage
// humain d'un desaccord de A (server._muter_decision_article) pose
// screening_decision_fulltext_original, la decision du modele 1 de A : sans tiret bas, elle
// traverse le chargeur, son drapeau _human_corrected non. Le moteur la lisait comme la decision
// du modele 1 de B : B mesurait 4 paires et 4 accords (kappa 1), l'item 8 publiait 1 desaccord
// et kappa 0,5, ou 0,6 quand le registre reposait sur B la decision de A (il garde la trace
// qu'il trouve). Une trace sans son drapeau n'est pas une decision humaine de CETTE execution :
// meme signe que __humain (NOTICE_SAUTEE_v1) et __humainFT (statsInto). Avec son drapeau
// (reprise du run corrige), elle reste.
for (let __e = 0; __e < articles.length; __e++) { const __a = articles[__e]; if (__a && typeof __a === 'object') { delete __a.screening_decision_fulltext_2; delete __a._screening_decision_fulltext_2_repli; delete __a.screening_agreement_fulltext; if (!__a._human_corrected) delete __a.screening_decision_fulltext_original; } }

const results = [];
const stats = { total: articles.length, eligible: 0, confirmed: 0, revised: 0, no_pdf: 0, no_decision: 0, extract_failed: 0, stopped: 0 };

// ARRET_SORT_DE_LA_BOUCLE_v1 (2026-10-19). CE QUI ETAIT FAUX, incident du jour (Lecture integrale de
// 2 820 PDF arretee) rejoue par tests/test_arret_sort_de_la_boucle.py : cette boucle ne regardait pas
// la reponse d'arret du relais (`ultralab_cancelled`, src/proxy.py). Elle relisait le PDF de chaque
// article restant, recevait une reponse vide et marquait l'article « llm_error », decision du tri sur
// resume recopiee. Mesure sur le cas : 6 lectures, 6 appels, et 4 articles restants sur 6 en erreur,
// indiscernables d'une vraie panne. CE QUI CHANGE : au premier refus nomme (lecture du PDF, qui nomme
// desormais son module, ou appel au modele), la boucle cesse de travailler. L'article en cours et les
// suivants qui demandaient une lecture sortent « stopped », SANS decision de texte integral (la reprise
// les retrouve : src/run_resume.py, PENDING) et sans pas publie ; ceux qui n'en demandaient pas
// (exclus sur resume, sans PDF) sortent comme dans un run complet. La seconde lecture n'est pas
// lancee, ou sort au premier refus. Une exception d'appel reste une erreur et la boucle continue :
// seul l'arret fait sortir. Une decision de texte integral anterieure ne reste que si elle est
// humaine, meme regle que NOTICE_SAUTEE_v1.
let __ftArret = false;
function __ftNonLu(article, orig) {
  const a = Object.assign({}, article, {
    screening_reason_fulltext: 'Non lu : arret du run demande avant sa lecture / Not read: run stop requested before its reading',
    screening_decision_initial: orig,
    _fulltext_status: 'stopped'
  });
  if (!(a._human_corrected && ('screening_decision_fulltext_original' in a))) delete a.screening_decision_fulltext;
  return a;
}

for (let i = 0; i < articles.length; i++) {
  const article = articles[i];
  const orig_decision = article.screening_decision || '';
  const pdf_path = article.pdf_local || '';

  // FULLTEXT_ELIGIBILITY_v2 : on analyse tout SAUF les Exclude deja decides
  // (permet le screening direct depuis dossier de PDFs sans pre-screening)
  if (orig_decision === 'Exclude') {
    // NOTICE_SAUTEE_v1 (mesure du 2026-09-10) : une notice sautee n'a pas ete lue par CETTE
    // execution. Elle arrivait avec les champs d'une lecture anterieure (reprise de tout le
    // corpus apres qu'une decision sur resume l'a exclue) et les gardait : statut « confirmed »,
    // decision Include, si bien que l'assemblage publiait 2 articles evalues et 2 inclus pour
    // une seule lecture reelle. Ces champs sont retires ici ; ceux de la seconde lecture l'ont
    // deja ete a l'entree du noeud (SECONDE_LECTURE_DE_CETTE_EXECUTION_v1). SEULE EXCEPTION : une
    // decision HUMAINE sur texte integral (trace screening_decision_fulltext_original posee par la
    // correction), qu'on ne perd pas ; son statut de lecture, lui, part.
    const __saut = Object.assign({}, article, {
      _fulltext_skipped: 'already excluded by pre-screening'
    });
    const __humain = !!__saut._human_corrected && ('screening_decision_fulltext_original' in __saut);
    const __perimes = ['_fulltext_status'];
    if (!__humain) __perimes.push('screening_decision_fulltext');
    for (let __p = 0; __p < __perimes.length; __p++) delete __saut[__perimes[__p]];
    results.push({ json: __saut });
    __ftSautes++; __ftSansTravail++;
    continue;
  }

  if (!pdf_path) {
    stats.no_pdf++;
    results.push({ json: Object.assign({}, article, {
      screening_decision_fulltext: orig_decision,
      screening_reason_fulltext: 'PDF non disponible - decision initiale conservee',
      screening_decision_initial: orig_decision,
      _fulltext_status: 'no_pdf'
    })});
    __ftSautes++; __ftSansTravail++;
    continue;
  }

  // ARRET_SORT_DE_LA_BOUCLE_v1 : apres l'arret, plus aucune lecture ni aucun appel.
  if (__ftArret) { stats.stopped++; results.push({ json: __ftNonLu(article, orig_decision) }); continue; }

  stats.eligible++;

  // === 1. Extract PDF text ===
  // Les pas en attente partent AVANT la lecture : elle peut durer jusqu'a son delai.
  await __ftAvancer.call(this);
  let full_text = '';
  try {
    const resp = await this.helpers.httpRequest({
      method: 'POST',
      url: PROXY + '/extract-pdf',
      // LA LECTURE NOMME SON MODULE (ARRET_SORT_DE_LA_BOUCLE_v1, 2026-10-19) : le relais refuse
      // alors la lecture d'un run qu'on arrete et la compte comme signe de vie de ce run
      // (src/proxy.py, `_handle_extract_pdf`). Sans module, il lisait chaque PDF restant pendant
      // l'arret, sans rien en dire.
      body: JSON.stringify({ pdf_path: pdf_path, max_chars: 30000, skip_biblio: true, _ultralab_module: __ftMode }),
      headers: { 'Content-Type': 'application/json' },
      json: true,
      timeout: 60000,
      ignoreHttpStatusErrors: true
    });
    if (resp && resp.ultralab_cancelled === true) {
      __ftArret = true;
    } else if (resp && resp.success && resp.text) {
      full_text = resp.text.substring(0, 25000);
    } else {
      throw new Error((resp && resp.error) || 'PDF extraction failed');
    }
  } catch (e) {
    // PDF_INTROUVABLE_v1 (2026-10-08, lot suivi). Un chemin de PDF dont le FICHIER manque (dossier
    // deplace ou renomme) etait compte extract_failed, publie « Texte du PDF illisible », et « Sans
    // PDF » restait a 0. Refutation du tour 6, rejouee le 2026-10-08 par le vrai gestionnaire du
    // relais (404, corps « PDF not found: <chemin> ») et ce nœud : 3 fichiers absents sur 3 comptes
    // illisibles. Ils prennent le statut no_pdf, comme un article sans chemin, et ne comptent pas
    // de lecture (le relais n'ouvre rien). Deux formes sont reconnues, le source du moteur de
    // workflows n'etant pas sur ce poste : le corps du relais, quand l'option
    // ignoreHttpStatusErrors posee sur la requete est suivie, et le message « status code 404 »
